/// The built-in role every principal holds, including anonymous ones.
pub fn public_role() -> RoleId {
    RoleId("public".to_string())
}

/// The built-in role that may do anything inside its tenant.
pub fn owner_role() -> RoleId {
    RoleId("owner".to_string())
}

/// What the kernel asks of a [`Value`].
pub trait ValueExt {
    /// True for `Null`, the absence of a value.
    fn is_null(&self) -> bool;
    /// The text of a `Str`.
    fn as_str(&self) -> Option<&str>;
    /// The name of this value's shape, for messages.
    fn kind(&self) -> &'static str;
}

impl ValueExt for Value {
    fn is_null(&self) -> bool {
        matches!(self, Value::Null)
    }

    fn as_str(&self) -> Option<&str> {
        match self {
            Value::Str(s) => Some(s),
            _ => None,
        }
    }

    fn kind(&self) -> &'static str {
        match self {
            Value::Null => "null",
            Value::Bool(_) => "bool",
            Value::Int(_) => "int",
            Value::Str(_) => "string",
            Value::Time(_) => "timestamp",
            Value::Ref(_) => "reference",
            Value::List(_) => "list",
        }
    }
}

/// What the kernel asks of a [`FieldType`].
pub trait FieldTypeExt {
    /// Whether a non-null value has this type. Reference targets are checked against state
    /// separately, because that needs the records.
    fn admits(&self, value: &Value) -> bool;
    /// The type's name, for messages.
    fn name(&self) -> String;
    /// The object type this field refers to, directly or as list elements.
    fn ref_target(&self) -> Option<(&ObjectTypeId, OnDelete, bool)>;
}

impl FieldTypeExt for FieldType {
    fn admits(&self, value: &Value) -> bool {
        match (self, value) {
            (FieldType::Str, Value::Str(_))
            | (FieldType::Int, Value::Int(_))
            | (FieldType::Bool, Value::Bool(_))
            | (FieldType::Time, Value::Time(_))
            | (FieldType::Ref { .. }, Value::Ref(_))
            | (FieldType::File { .. }, Value::Str(_))
            | (FieldType::Language, Value::Str(_)) => true,
            (FieldType::List(inner), Value::List(items)) => {
                items.iter().all(|item| inner.admits(item))
            }
            _ => false,
        }
    }

    fn name(&self) -> String {
        match self {
            FieldType::Str => "string".into(),
            FieldType::Int => "int".into(),
            FieldType::Bool => "bool".into(),
            FieldType::Time => "timestamp".into(),
            FieldType::Ref { target, .. } => format!("reference<{target}>"),
            FieldType::List(inner) => format!("list<{}>", inner.name()),
            FieldType::File { .. } => "file".into(),
            FieldType::Language => "language".into(),
        }
    }

    fn ref_target(&self) -> Option<(&ObjectTypeId, OnDelete, bool)> {
        match self {
            FieldType::Ref { target, on_delete } => Some((target, *on_delete, false)),
            FieldType::List(inner) => match inner.as_ref() {
                FieldType::Ref { target, on_delete } => Some((target, *on_delete, true)),
                _ => None,
            },
            _ => None,
        }
    }
}

/// The record ids a value refers to.
pub fn refs_in(value: &Value) -> Vec<RecordId> {
    match value {
        Value::Ref(id) => vec![*id],
        Value::List(items) => items.iter().flat_map(refs_in).collect(),
        _ => Vec::new(),
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn names_are_validated_on_construction_and_on_deserialisation() {
        assert!(ObjectTypeId::new("post").is_ok());
        assert!(ObjectTypeId::new("Post").is_err());
        assert!(ObjectTypeId::new("").is_err());
        assert!(ObjectTypeId::new("a-b").is_err());
        assert!(serde_json::from_str::<FieldId>("\"1x\"").is_err());
        assert_eq!(
            serde_json::from_str::<FieldId>("\"title\"")
                .unwrap()
                .as_str(),
            "title"
        );
        assert!(PrincipalId::new("user:ines").is_ok());
        assert!(PrincipalId::new("has space").is_err());
    }
}
